#!/usr/bin/env python3
from pwn import *
import itertools

def is_valid_move(x, y, visited, board_size=8):
    return 0 <= x < board_size and 0 <= y < board_size and (x, y) not in visited

def try_path(path):
    try:
        # Try locally first
        p = process('./ctf_files/maze_public')
        p.recvuntil(b"Please type your input:")
        p.sendline(path.encode())
        result = p.recvall(timeout=1)
        p.close()

        if b"Try again" not in result:
            # If local test passes, try remote
            r = remote("rev.chal.csaw.io", 5000)
            r.recvuntil(b"Please type your input:")
            r.sendline(path.encode())
            result = r.recvall(timeout=1)
            r.close()
            return result
    except Exception as e:
        print(f"Error: {e}")
    return None

def find_path_segment(start_x, start_y, length, visited=None):
    if visited is None:
        visited = {(start_x, start_y)}

    if length == 0:
        return ""

    moves = {
        1: (-2, 1),   # Move 1
        2: (-1, 2),   # Move 2
        3: (1, 2),    # Move 3
        4: (2, 1),    # Move 4
        5: (2, -1),   # Move 5
        6: (1, -2),   # Move 6
        7: (-1, -2),  # Move 7
        8: (-2, -1)   # Move 8
    }

    # Try each move
    for move_num, (dx, dy) in moves.items():
        next_x = start_x + dx
        next_y = start_y + dy

        if is_valid_move(next_x, next_y, visited):
            new_visited = visited | {(next_x, next_y)}
            rest = find_path_segment(next_x, next_y, length - 1, new_visited)
            if rest is not None:
                return str(move_num) + rest

    return None

def divide_and_conquer():
    # Starting position
    start_positions = [(i, j) for i in range(8) for j in range(8)]

    # Try different segment lengths
    segment_length = 16  # Each segment will be 16 moves
    total_moves = 64

    for start_x, start_y in start_positions:
        print(f"Trying start position ({start_x}, {start_y})")

        # Try to find first segment
        first_segment = find_path_segment(start_x, start_y, segment_length)
        if not first_segment:
            continue

        # Try each segment
        for _ in range(total_moves // segment_length):
            full_path = first_segment
            if len(full_path) == total_moves:
                result = try_path(full_path)
                if result and b"Try again" not in result:
                    print(f"Found valid path: {full_path}")
                    print(f"Result: {result}")
                    return full_path, result

    return None, None

def main():
    print("Starting maze solver...")
    path, result = divide_and_conquer()

    if path:
        print("\nSuccess!")
        print(f"Path found: {path}")
        print(f"Length: {len(path)}")
        print(f"Result: {result}")
    else:
        print("\nNo valid path found")

if __name__ == "__main__":
    main()

