from pwn import *
import random

N = 8

# Knight's moves mapping
MOVES = [
    (-2, 1),  # 1
    (-1, 2),  # 2
    (1, 2),   # 3
    (2, 1),   # 4
    (2, -1),  # 5
    (1, -2),  # 6
    (-1, -2), # 7
    (-2, -1)  # 8
]

def is_valid(x, y):
    return 0 <= x < N and 0 <= y < N

def get_degree(x, y, board):
    count = 0
    for dx, dy in MOVES:
        next_x, next_y = x + dx, y + dy
        if is_valid(next_x, next_y) and board[next_x][next_y] == -1:
            count += 1
    return count

def get_move_score(x, y, board, move_count):
    score = get_degree(x, y, board)

    # Early game edge preference
    if move_count < 20:
        if x in [0, N-1] or y in [0, N-1]:
            score -= 2
        if x in [0, N-1] and y in [0, N-1]:
            score -= 1

    # Mid game central preference
    elif move_count < 40:
        center_dist = abs(x - 3.5) + abs(y - 3.5)
        score += center_dist * 0.5

    # Late game connectivity bonus
    else:
        for dx, dy in MOVES:
            next_x, next_y = x + dx, y + dy
            if is_valid(next_x, next_y) and board[next_x][next_y] != -1:
                score -= 0.5

    return score

def can_reach_start(x, y):
    for dx, dy in MOVES:
        if (x + dx, y + dy) == (0, 0):
            return True
    return False

def solve_knights_tour():
    attempts = 0
    max_attempts = 100

    while attempts < max_attempts:
        attempts += 1
        board = [[-1 for _ in range(N)] for _ in range(N)]
        path = []
        pos = [(0, 0)]
        board[0][0] = 0
        move_count = 0

        while len(pos) < N * N:
            x, y = pos[-1]
            candidates = []

            for i, (dx, dy) in enumerate(MOVES, 1):
                next_x, next_y = x + dx, y + dy
                if is_valid(next_x, next_y) and board[next_x][next_y] == -1:
                    score = get_move_score(next_x, next_y, board, move_count)

                    # Late game closing bonus
                    if len(pos) > 60 and can_reach_start(next_x, next_y):
                        score -= 3

                    candidates.append((score, random.random(), i, next_x, next_y))

            if not candidates:
                break

            candidates.sort()
            _, _, move, next_x, next_y = candidates[0]

            path.append(move)
            board[next_x][next_y] = len(pos)
            pos.append((next_x, next_y))
            move_count += 1

        # Check if we have a complete tour
        if len(pos) == N * N:
            last_x, last_y = pos[-1]
            if can_reach_start(last_x, last_y):
                return path

    return None

def test_path(moves):
    visited = set([(0, 0)])
    x, y = 0, 0

    for move in moves:
        dx, dy = MOVES[move - 1]
        x, y = x + dx, y + dy
        if not is_valid(x, y) or (x, y) in visited:
            return False
        visited.add((x, y))

    return len(visited) == N * N and can_reach_start(x, y)

def main():
    print("Finding knight's tour...")
    solution = solve_knights_tour()

    if not solution:
        print("Failed to find valid tour")
        return

    if not test_path(solution):
        print("Invalid tour generated")
        return

    move_sequence = ''.join(map(str, solution))
    print(f"Found tour: {move_sequence}")

    try:
        r = remote('rev.chal.csaw.io', 5000)
        r.sendline(move_sequence.encode())
        response = r.recvall(timeout=5).decode()
        print(f"Server response: {response}")
        if "Try again" not in response:
            print(f"Success! Valid tour found: {move_sequence}")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        r.close()

if __name__ == "__main__":
    main()

from pwn import *

def generate_moves():
    # Systematic pattern that covers the board
    pattern = []
    for i in range(8):
        if i % 2 == 0:
            pattern.extend([2, 3, 6, 5, 4, 1, 2, 3])
        else:
            pattern.extend([6, 5, 2, 3, 8, 7, 6, 5])
    return ''.join(map(str, pattern[:63]))  # 63 moves to complete the tour

def test_solution(moves):
    try:
        r = remote('rev.chal.csaw.io', 5000)
        print(f"Testing move sequence: {moves}")
        r.sendline(moves.encode())
        response = r.recvall(timeout=5).decode()
        print(f"Server response: {response}")
        return response
    except Exception as e:
        print(f"Error: {e}")
        return str(e)
    finally:
        r.close()

def main():
    print("Testing systematic knight's tour pattern...")
    moves = generate_moves()
    response = test_solution(moves)
    if "flag{" in response.lower():
        print("Success! Found correct tour!")
        return True
    return False

if __name__ == "__main__":
    main()
